/*
 * Modified by Actuna Sp. z o.o.:
 *   Z-10: singleInstance - with several instances a cron trigger runs on the
 *   instance that claims it, an interval or "once after start" trigger only on
 *   the leader; "standby" status on an instance that is not the leader
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

module.exports = function(RED) {
    "use strict";
    const {scheduleTask, CronosExpression} = require("cronosjs");

    // Z-10: ttl of the claim of a cron trigger - the period of the cron
    // expression, at least 1 minute (tolerance for clock differences between
    // the instances) and at most 1 hour
    const CLAIM_TTL_MIN = 60000;
    const CLAIM_TTL_MAX = 3600000;
    function cronClaimTtl(crontab, scheduledTime) {
        let period = CLAIM_TTL_MIN;
        try {
            const next = CronosExpression.parse(crontab).nextDate(new Date(scheduledTime));
            if (next) {
                period = next.getTime() - scheduledTime;
            }
        } catch (err) {
            // keep the minimum
        }
        return Math.min(Math.max(period, CLAIM_TTL_MIN), CLAIM_TTL_MAX);
    }

    function InjectNode(n) {
        RED.nodes.createNode(this,n);

        /* Handle legacy */
        if(!Array.isArray(n.props)){
            n.props = [];
            n.props.push({
                p:'payload',
                v:n.payload,
                vt:n.payloadType
            });
            n.props.push({
                p:'topic',
                v:n.topic,
                vt:'str'
            });
        } else {
            for (var i=0,l=n.props.length; i<l; i++) {
                if (n.props[i].p === 'payload' && !n.props[i].hasOwnProperty('v')) {
                    n.props[i].v = n.payload;
                    n.props[i].vt = n.payloadType;
                } else if (n.props[i].p === 'topic' && n.props[i].vt === 'str' && !n.props[i].hasOwnProperty('v')) {
                    n.props[i].v = n.topic;
                }
            }
        }

        this.props = n.props;
        this.repeat = n.repeat;
        this.crontab = n.crontab;
        this.once = n.once;
        this.onceDelay = (n.onceDelay || 0.1) * 1000;
        this.singleInstance = n.singleInstance === true;
        this.interval_id = null;
        this.cronjob = null;
        var node = this;

        // Z-10: coordination of instances - only with singleInstance and when
        // the runtime provides it; otherwise every trigger fires as before
        const coordination = (this.singleInstance && RED.coordination) ? RED.coordination : null;

        // interval and "once after start": only the leader fires (D-14)
        function fireIfLeader() {
            if (!coordination || coordination.isLeader()) {
                node.emit("input", {});
            }
        }
        // cron: the instance that claims "inject:<id>:<scheduled time>" fires
        function fireCron(scheduledTime) {
            if (!coordination) {
                node.emit("input", {});
                return;
            }
            const time = typeof scheduledTime === "number" ? scheduledTime : Date.now();
            const key = "inject:" + node.id + ":" + new Date(time).toISOString();
            let claimed;
            try {
                claimed = Promise.resolve(coordination.claim(key, cronClaimTtl(node.crontab, time)));
            } catch (err) {
                claimed = Promise.reject(err);
            }
            claimed.then(function(claim) {
                if (claim) {
                    node.emit("input", {});
                }
            }).catch(function(err) {
                node.warn(RED._("inject.errors.claim-failed", {error: err.toString()}));
            });
        }
        function showLeadership(isLeader) {
            if (isLeader) {
                node.status({});
            } else {
                node.status({fill: "grey", shape: "ring", text: RED._("inject.standby")});
            }
        }

        node.props.forEach(function (prop) {
            if (prop.vt === "jsonata") {
                try {
                    var val = prop.v ? prop.v : "";
                    prop.exp = RED.util.prepareJSONataExpression(val, node);
                }
                catch (err) {
                    node.error(RED._("inject.errors.invalid-expr", {error:err.message}));
                    prop.exp = null;
                }
            }
        });

        if (node.repeat > 2147483) {
            node.error(RED._("inject.errors.toolong", this));
            delete node.repeat;
        }

        node.repeaterSetup = function () {
            if (this.repeat && !isNaN(this.repeat) && this.repeat > 0) {
                this.repeat = this.repeat * 1000;
                this.debug(RED._("inject.repeat", this));
                this.interval_id = setInterval(function() {
                    fireIfLeader();
                }, this.repeat);
            } else if (this.crontab) {
                this.debug(RED._("inject.crontab", this));
                this.cronjob = scheduleTask(this.crontab,(scheduledTime) => { fireCron(scheduledTime) });
            }
        };

        // Leader-gated triggers show "standby" on an instance that is not the leader (R-21)
        const leaderGated = this.once || (this.repeat && !isNaN(this.repeat) && this.repeat > 0);
        if (coordination && leaderGated) {
            coordination.onLeaderChange(node, showLeadership);
            if (!coordination.isLeader()) {
                showLeadership(false);
            }
        }

        if (this.once) {
            this.onceTimeout = setTimeout( function() {
                fireIfLeader();
                node.repeaterSetup();
            }, this.onceDelay);
        } else {
            node.repeaterSetup();
        }

        this.on("input", function(msg, send, done) {
            const errors = [];
            let props = this.props;
            if (msg.__user_inject_props__ && Array.isArray(msg.__user_inject_props__)) {
                props = msg.__user_inject_props__;
            }
            delete msg.__user_inject_props__;
            props = [...props]
            function evaluateProperty(doneEvaluating) {
                if (props.length === 0) { 
                    doneEvaluating()
                    return
                }
                const p = props.shift()
                const property = p.p;
                const value = p.v !== undefined ? p.v : '';
                const valueType = p.vt !== undefined ? p.vt : 'str';
                if (property) {
                    if (valueType === "jsonata") {
                        if (p.v) {
                            try {
                                var exp = RED.util.prepareJSONataExpression(p.v, node);
                                RED.util.evaluateJSONataExpression(exp, msg, (err, newValue) => {
                                    if (err) {
                                        errors.push(RED._("inject.errors.invalid-expr",{error:err.message}))
                                    } else {
                                        RED.util.setMessageProperty(msg,property,newValue,true);
                                    }
                                    evaluateProperty(doneEvaluating)
                                });
                            } catch (err) {
                                errors.push(err.message);
                                evaluateProperty(doneEvaluating)
                            }
                        } else {
                            evaluateProperty(doneEvaluating)
                        }
                    } else {
                        try {
                            RED.util.evaluateNodeProperty(value, valueType, node, msg, (err, newValue) => {
                                if (err) {
                                    errors.push(err.toString())
                                } else {
                                    RED.util.setMessageProperty(msg,property,newValue,true);
                                }
                                evaluateProperty(doneEvaluating)
                            })
                        } catch (err) {
                            errors.push(err.toString());
                            evaluateProperty(doneEvaluating)
                        }
                    }
                } else {
                    evaluateProperty(doneEvaluating)
                }
            }
           
            evaluateProperty(() => {
                if (errors.length) {
                    done(errors.join('; '));
                } else {
                    send(msg);
                    done();
                }
            })
        });
    }

    RED.nodes.registerType("inject",InjectNode);

    InjectNode.prototype.close = function() {
        if (this.onceTimeout) {
            clearTimeout(this.onceTimeout);
        }
        if (this.interval_id != null) {
            clearInterval(this.interval_id);
        } else if (this.cronjob != null) {
            this.cronjob.stop();
            delete this.cronjob;
        }
    };

    RED.httpAdmin.post("/inject/:id", RED.auth.needsPermission("inject.write"), function(req,res) {
        var node = RED.nodes.getNode(req.params.id);
        if (node != null) {
            try {
                if (req.body && req.body.__user_inject_props__) {
                    node.receive(req.body);
                } else {
                    node.receive();
                }
                res.sendStatus(200);
            } catch(err) {
                res.sendStatus(500);
                node.error(RED._("inject.failed",{error:err.toString()}));
            }
        } else {
            res.sendStatus(404);
        }
    });
}
